import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CCCdsIgc.js";const _=JSON.parse('{"title":"无人值守任务","description":"","frontmatter":{},"headers":[],"relativePath":"admin/unattended.md","filePath":"admin/unattended.md"}'),n={name:"admin/unattended.md"};function o(i,t,l,s,h,u){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="无人值守任务" tabindex="-1">无人值守任务 <a class="header-anchor" href="#无人值守任务" aria-label="Permalink to &quot;无人值守任务&quot;">​</a></h1><p>员工电脑上的定时任务要电脑开着才会跑。<strong>无人值守任务</strong>由服务端按时间表派到一台常开的<strong>执行机</strong>上执行，员工下班关机也照常跑；做完的结果作为「<strong>定时报告</strong>」发到指定部门或电脑的消息中心。</p><p>适合：每天早上的产量日报、每周一的生产周报、每小时检查一次异常停机……凡是「到点拉数据、出报告」的事。</p><h2 id="准备一台执行机" tabindex="-1">准备一台执行机 <a class="header-anchor" href="#准备一台执行机" aria-label="Permalink to &quot;准备一台执行机&quot;">​</a></h2><ol><li>找一台不给员工用的电脑或虚拟机（Windows 10/11），装 FlyknitBuddy，用专门的账号登录；</li><li>Windows 设成<strong>自动登录</strong>、<strong>开机自动启动 FlyknitBuddy</strong>，电源计划设成「从不睡眠」；</li><li>把这台电脑要用的连接器（如中台）、技能装好、登录好；</li><li>在「设备列表」里给它写个备注（如「无人值守执行机」），需要的话单独给它设安全设置。</li></ol><h2 id="建任务" tabindex="-1">建任务 <a class="header-anchor" href="#建任务" aria-label="Permalink to &quot;建任务&quot;">​</a></h2><p>后台「<strong>运维 → 无人值守任务</strong>」：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>交给 AI 的要求</td><td>像平时跟 FlyknitBuddy 说话一样写，比如「用中台查上周各车间的产量、达成率和不良率，和前一周对比，用表格列出，最后写三条需要关注的地方」</td></tr><tr><td>时间</td><td>每天 / 工作日 / 每周几 / 每月几号 / 从某个时间起每隔几小时；时区选越南或中国</td></tr><tr><td>执行机</td><td>选上面准备好的那台</td></tr><tr><td>结果发给</td><td>部门、个别电脑；<strong>都不选就不发</strong>，只在这页的执行记录里看</td></tr><tr><td>权限上限</td><td>仅可查看 / 工作区内修改（没有完全权限）</td></tr><tr><td>只预演</td><td>新建默认打开：只列出会做什么、不真的改。看过几次结果没问题再关掉</td></tr></tbody></table><p>页面右上角的<strong>总开关</strong>默认关闭，只有超级管理员能打开。关着时到点不派发；打开后不会把关着期间错过的一次补跑一堆。</p><h2 id="规则" tabindex="-1">规则 <a class="header-anchor" href="#规则" aria-label="Permalink to &quot;规则&quot;">​</a></h2><ul><li>执行机前没有人：需要员工确认的操作一律不做，被拒的会写在结果里；</li><li>上一次还没做完，这一次自动跳过；</li><li>建任务、改任务、立即运行需要「能下发指令」的管理员账号；</li><li>做失败的报告会标为重要，写明原因（比如连接器没连上）。</li></ul>',11)])])}const p=a(n,[["render",o]]);export{_ as __pageData,p as default};
